function test_demo_2026(full_defaults)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Exercise the actual shipped scripts in an isolated mirror, without a keypress.
% Default focused regression shortens transients and disables figure exports.
% test_demo_2026(true) uses unmodified PLL settings, including JPEG exports.

if nargin<1
    full_defaults=false;
end
validateattributes(full_defaults,{'logical','numeric'},{'scalar','binary'});
tool_directory=fileparts(mfilename('fullpath'));
repository_directory=fileparts(tool_directory);
path_before=path;
directory_before=pwd;
visibility_before=get(0,'defaultfigurevisible');
figures_before=findall(0,'type','figure');
temporary=tempname();
[ok,message]=mkdir(temporary);
assert(ok,message);
cleanup=onCleanup(@() cleanup_test(temporary,path_before,directory_before,visibility_before,figures_before));
mkdir(fullfile(temporary,'pn'));
mkdir(fullfile(temporary,'pll_synth'));
copyfile(fullfile(repository_directory,'pn','aa_generate_ros2100_example.m'),fullfile(temporary,'pn'));
demo_text=fileread(fullfile(repository_directory,'demo_2026.m'));
demo_text=strrep(demo_text,'demo_pause_for_key=1;','demo_pause_for_key=0;');
write_script(fullfile(temporary,'demo_2026.m'),demo_text);
pll_text=fileread(fullfile(tool_directory,'aa_demo_ROS_based_synthesizer_runPLL.m'));
if ~full_defaults
    pll_text=strrep(pll_text,'pll_inputs_s.bSaveFigs=1;','pll_inputs_s.bSaveFigs=0;');
    pll_text=strrep(pll_text,'pll_inputs_s.transient_tmax_s=15e-3;','pll_inputs_s.transient_tmax_s=1e-3;');
    pll_text=strrep(pll_text,'pll_inputs_s.transient_points=12501;','pll_inputs_s.transient_points=301;');
    pll_text=strrep(pll_text,'pll_inputs_s.transient_nl_steps_per_ref=100;','pll_inputs_s.transient_nl_steps_per_ref=10;');
end
write_script(fullfile(temporary,'pll_synth','aa_demo_ROS_based_synthesizer_runPLL.m'),pll_text);
addpath(tool_directory,fullfile(repository_directory,'pn'),temporary);
set(0,'defaultfigurevisible','off');
if exist('OCTAVE_VERSION','builtin')
    graphics_toolkit('qt');
end
sentinel=figure('name','Unrelated figure survives demo');
sentinel_line=plot(1:3,[4 5 6]);
cd(temporary);

% Root script generates the profile, shows both source plots, then runs the
% center design and the fixed-filter sweep with the existing viewer enabled.
transcript=evalc('demo_2026;');
assert(~isempty(strfind(transcript,'Mini-Circuits ROS-2100-119+')));
assert(~isempty(strfind(transcript,'not a measured gain')));
assert(~isempty(strfind(transcript,'Fixed filter:')));
assert(isgraphics(sentinel_line));
assert(strcmp(pwd,temporary));
assert(exist(fullfile(temporary,'pll_synth','_demo_2026','ROS_2100_119_profile.mat'),'file')==2);
assert(isequal(PLL_DATA_s.values,[1350 1537.5 1725 1912.5 2100]*1e6));
assert(strcmp(PLL_DATA_s.parameter,'fout_desired_Hz'));
assert(all(PLL_DATA_s.completed) && numel(PLL_DATA_s.cases)==5);
center=ROS_CENTER_DATA_s.cases{1};
assert(center.requested_inputs.fout_desired_Hz==1725e6);
assert(center.requested_inputs.BW_desired_Hz==5e3);
assert(~center.requested_inputs.filter_override && ~center.requested_inputs.filter_override_3rdpole_only);
% The core reports the closest log-grid crossover, rather than a root solve.
grid_ratio=(center.requested_inputs.fstop_main_Hz/center.requested_inputs.fstart_main_Hz)^ ...
    (1/(center.requested_inputs.fsweep_main_pts-1));
assert(abs(log(center.BW_actual_Hz/5e3))<log(grid_ratio));
assert(abs(center.PM_actual_deg-55)<2);
gains=zeros(1,5);
bandwidths=zeros(1,5);
for ii=1:5
    result=PLL_DATA_s.cases{ii};
    assert(result.requested_inputs.filter_override==1);
    assert(result.requested_inputs.filter_override_3rdpole_only==0);
    assert(isequal(result.components,center.components));
    assert(result.requested_inputs.BW_desired_Hz==5e3);
    expected=select_pn_profile(demo_ros_profile_s,PLL_DATA_s.values(ii),'interpolate');
    assert(isequal(result.vco_characterization.f,expected.f));
    assert(max(abs(result.vco_characterization.n-expected.n))<1e-12);
    assert(result.Kvco_Hz_volt==expected.kvco);
    assert(result.effective_inputs.Kvco_Hz_volt==expected.kvco);
    assert(result.Fvco_Hz==PLL_DATA_s.values(ii));
    source=load(result.effective_inputs.FileVCO,'pn_struct');
    assert(isequal(source.pn_struct,result.vco_characterization));
    assert(numel(result.small_signal.time_s)==result.requested_inputs.transient_points);
    expected_steps=ceil(result.requested_inputs.transient_tmax_s/ ...
        (1/(result.requested_inputs.Fref_Hz*result.requested_inputs.transient_nl_steps_per_ref)));
    assert(numel(result.nonlinear.time_s)==expected_steps+1);
    if ii==3
        assert(strcmp(result.vco_selection_s.mode,'exact'));
        assert(numel(result.vco_characterization.f)==20);
    else
        assert(strcmp(result.vco_selection_s.mode,'interpolate'));
        assert(numel(result.vco_characterization.f)==4);
    end
    gains(ii)=result.Kvco_Hz_volt;
    bandwidths(ii)=result.BW_actual_Hz;
    if full_defaults
        [case_directory,case_basename]=fileparts(result.effective_inputs.def_filename);
        if isempty(case_directory)
            case_directory=fileparts(result.effective_inputs.FileVCO);
        end
        suffixes={'_R2_R3Noise','_VCO','_contribs_total','_totals','_transient','_transient_nl'};
        for jj=1:numel(suffixes)
            info=imfinfo(fullfile(case_directory,[case_basename suffixes{jj} '.jpg']));
            assert(strcmpi(info.Format,'jpg') || strcmpi(info.Format,'jpeg'));
        end
        assert(exist(fullfile(case_directory,[case_basename '_results.csv']),'file')==2);
    end
end
assert(numel(unique(gains))==5);
assert(numel(unique(bandwidths))>1);
assert(isequal(PLL_DATA_s.config_s.run_options_s.center_design_s.components,center.components));
assert(isgraphics(ros_plot_figure) && isgraphics(ros_kvco_figure));
viewers=findall(0,'type','figure','tag','pll_data_viewer');
assert(~isempty(viewers));
viewer=viewers(1);
details=strjoin(cellstr(get(findobj(viewer,'tag','pll_view_details'),'string')),' ');
assert(~isempty(strfind(details,'VCO profile selection:')));
assert(~isempty(strfind(details,'vco_profile_s:')));
assert(~isempty(strfind(details,'21-point structure array (stored in dataset)')));
assert(~isempty(strfind(details,'center_design_s:')));
assert(~isempty(strfind(details,sprintf('BW_actual_Hz = %.9g',center.BW_actual_Hz))));
controls=findobj(viewer,'tag','pll_view_kind');
for mode=[1 3 9 10 11 12 14 16]
    set(controls,'value',mode);
    callback=get(controls,'callback');
    callback(controls,[]);
    status=findobj(viewer,'tag','pll_view_status');
    assert(isempty(strfind(get(status,'string'),'Plot failed:')));
end
reloaded=load(PLL_DATA_s.dataset_path,'pll_data_s');
assert(all(reloaded.pll_data_s.completed));
reopened=cc_pll_data_viewer(PLL_DATA_s.dataset_path);
assert(isgraphics(reopened));

% Repeated root execution replaces only its own source plots, and overwrites
% isolated outputs. No unrelated figures or measurements are changed.
if ~full_defaults
    old_lines=findobj(get(ros_kvco_figure,'currentaxes'),'type','line');
    evalc('demo_2026;');
    assert(~any(isgraphics(old_lines)));
    assert(isgraphics(sentinel_line));
    assert(all(PLL_DATA_s.completed));
    clear demo_ros_profile_s demo_output_directory demo_overwrite_results;
    evalc('aa_demo_ROS_based_synthesizer_runPLL;');
    assert(all(PLL_DATA_s.completed));
    assert(numel(demo_ros_profile_s.points)==21);
    assert(isgraphics(sentinel_line));
end

bad=PLL_DATA_s.config_s;
bad.pll_inputs_s.bUseVCOFromFile=0;
must_fail(@() rfdude_pll_validate_configuration(bad,temporary));
bad=PLL_DATA_s.config_s;
bad.run_options_s.bRunSweep=0;
bad.pll_inputs_s.fout_desired_Hz=3e9;
must_fail(@() rfdude_pll_validate_configuration(bad,temporary));
fprintf('demo_2026: provenance, center 5 kHz design, fixed filter, five ROS sources, transients and viewer passed.\n');
fprintf('Center achieved %.9g Hz / %.9g deg; five achieved bandwidths: %s Hz.\n', ...
    center.BW_actual_Hz,center.PM_actual_deg,mat2str(bandwidths,9));
end

function write_script(filename,text)
[file,message]=fopen(filename,'w');
assert(file~=-1,message);
cleanup=onCleanup(@() fclose(file));
assert(fprintf(file,'%s',text)==numel(text));
end

function must_fail(action)
failed=false;
try
    action();
catch exception
    failed=true;
    assert(~isempty(exception.message));
end
assert(failed,'Expected profile input to be rejected.');
end

function cleanup_test(temporary,path_before,directory_before,visibility_before,figures_before)
cd(directory_before);
path(path_before);
set(0,'defaultfigurevisible',visibility_before);
figures_now=findall(0,'type','figure');
for ii=1:numel(figures_now)
    if ~any(figures_now(ii)==figures_before)
        close(figures_now(ii));
    end
end
if exist(temporary,'dir')==7
    rmdir(temporary,'s');
end
end
